  const ARC_IDS = Object.keys(ARC_CONFIG);
  const SAGA_IDS = Object.keys(SAGA_CONFIG);
  const DEFAULT_ARC_ID = ARC_IDS[0] || "";
  const STAGE_BY_AREA = Object.fromEntries(STAGES.map(stage => [stage.areaId, stage]));
  const STAGES_BY_SAGA = STAGES.reduce((accumulator, stage) => {
    if (!accumulator[stage.sagaId]) accumulator[stage.sagaId] = [];
    accumulator[stage.sagaId].push(stage);
    return accumulator;
  }, {});
  const SAGAS_BY_ARC = Object.values(SAGA_CONFIG).reduce((accumulator, saga) => {
    if (!accumulator[saga.arcId]) accumulator[saga.arcId] = [];
    accumulator[saga.arcId].push(saga.id);
    return accumulator;
  }, {});

  ARC_IDS.forEach(arcId => {
    const orderedSagas = ARC_CONFIG[arcId]?.sagaOrder;
    if (Array.isArray(orderedSagas)) {
      SAGAS_BY_ARC[arcId] = orderedSagas.filter(sagaId => SAGA_CONFIG[sagaId]?.arcId === arcId);
    } else if (!Array.isArray(SAGAS_BY_ARC[arcId])) {
      SAGAS_BY_ARC[arcId] = [];
    }
  });

  SAGA_IDS.forEach(sagaId => {
    if (!Array.isArray(STAGES_BY_SAGA[sagaId])) STAGES_BY_SAGA[sagaId] = [];
  });

  const runtime = {
    api: undefined,
    observer: undefined,
    menuCloseBound: false,
    view: "arcs",
    lastSagaView: undefined,
    pendingSagaView: undefined,
    patched: {},
    rootScrollLock: undefined,
    viewportSyncBound: false
  };

  UltraMods.define({
    id: MOD_ID,
    name: "神话",
    description: "新增传说级故事剧情。天气三神（固拉多、盖欧卡、烈空坐）的传奇章节现已加入，敌人拥有高个体值（IV）。",
    image: "icon.png",
    version: "1.8",
    author: "UltraPokechill",
    category: "任务",
    hooks: {
      onToggle(api, payload) {
        runtime.api = api;
        if (payload.enabled) install(api);
        else uninstall();
      },
      onRefresh(api) {
        runtime.api = api;
        if (api.isEnabled(MOD_ID)) install(api);
      },
      onCombatStart(api, payload) {
        runtime.api = api;
        if (!api.isEnabled(MOD_ID)) return;
        prepareSagaAreaReward(payload?.areaId);
      },
      afterBattleSummaryRender(api) {
        runtime.api = api;
        if (!api.isEnabled(MOD_ID)) return;
        syncProgressFromAreas(api);
        hideSagaRejoin();
        restoreSagaMenuAfterBattle();
        renderMythosMenu();
      }
    }
  });

  function install(api) {
    runtime.api = api;
    ensureProgress(api);
    installStyles();
    patchCombatFunctions();
    defineSagaAreas(api);
    ensureMenuButton();
    ensureSagaMenu();
    installObservers();
    syncProgressFromAreas(api);
    syncMenuButton();
    renderMythosMenu();
  }

  function uninstall() {
    setRootScrollLocked(false);
    document.getElementById(MENU_BUTTON_ID)?.remove();
    document.getElementById(MENU_ID)?.remove();
    document.getElementById(DIALOG_ID)?.remove();
    document.getElementById(CUTSCENE_ID)?.remove();
    document.getElementById(STYLE_ID)?.remove();
    restoreCombatFunctions();

    if (runtime.observer) {
      runtime.observer.disconnect();
      runtime.observer = undefined;
    }
  }

  function makeArcView(arcId) {
    return `${ARC_VIEW_PREFIX}${arcId}`;
  }

  function getArcViewId(view) {
    if (typeof view !== "string" || !view.startsWith(ARC_VIEW_PREFIX)) return undefined;
    return view.slice(ARC_VIEW_PREFIX.length);
  }

  function isArcView(view) {
    return Boolean(getArcConfig(getArcViewId(view)));
  }

  function getArcIds() {
    return ARC_IDS.slice();
  }

  function getArcConfig(arcId) {
    return ARC_CONFIG[arcId];
  }

  function getSagaIds() {
    return SAGA_IDS.slice();
  }

  function getSagaConfig(sagaId) {
    return SAGA_CONFIG[sagaId];
  }

  function getArcForSaga(sagaId) {
    const saga = getSagaConfig(sagaId);
    return saga ? getArcConfig(saga.arcId) : undefined;
  }

  function getSagasForArc(arcId) {
    return (SAGAS_BY_ARC[arcId] || []).slice();
  }

  function getStagesForSaga(sagaId) {
    return (STAGES_BY_SAGA[sagaId] || []).slice();
  }

  function getStage(areaId) {
    return STAGE_BY_AREA[areaId];
  }

  function isSagaView(view) {
    return Boolean(getSagaConfig(view));
  }

  function isArcUnlocked(arcId) {
    const arc = getArcConfig(arcId);
    if (!arc) return false;
    return typeof arc.unlockRequirement === "function" ? arc.unlockRequirement() === true : true;
  }

  function getArcUnlockDescription(arcId) {
    const arc = getArcConfig(arcId);
    if (!arc) return "Locked";
    return arc.unlockDescription || `Unlock ${arc.name} first`;
  }

  function isSagaRequirementUnlocked(sagaId) {
    const saga = getSagaConfig(sagaId);
    if (!saga) return false;
    return typeof saga.unlockRequirement === "function" ? saga.unlockRequirement() === true : true;
  }

  function getSagaRequirementDescription(sagaId) {
    const saga = getSagaConfig(sagaId);
    if (!saga) return "Locked";
    return saga.unlockDescription || `Unlock ${saga.name} first`;
  }

  function getSagaAvailability(sagaId) {
    const saga = getSagaConfig(sagaId);
    const arc = getArcForSaga(sagaId);
    const arcLocked = arc ? !isArcUnlocked(arc.id) : true;
    const sagaLocked = !arcLocked && !isSagaRequirementUnlocked(sagaId);
    return {
      saga,
      arc,
      arcLocked,
      sagaLocked,
      unlocked: !arcLocked && !sagaLocked
    };
  }

  function getStageCombatRules(stage) {
    if (!stage) return {};
    const sagaRules = getSagaConfig(stage.sagaId)?.combatRules || {};
    const stageRules = stage.combatRules || {};
    return {
      ...sagaRules,
      ...stageRules,
      weather: {
        ...(sagaRules.weather || {}),
        ...(stageRules.weather || {})
      },
      enemyBuffRules: {
        ...(sagaRules.enemyBuffRules || {}),
        ...(stageRules.enemyBuffRules || {})
      }
    };
  }

  function getStageCutscene(stage) {
    return stage?.cutscene && typeof stage.cutscene === "object" ? stage.cutscene : undefined;
  }

  function getFinalBossRematchLock(stage) {
    const saga = stage ? getSagaConfig(stage.sagaId) : undefined;
    return {
      title: saga?.finalBossRematchLockedTitle || "Rematch Locked",
      message: saga?.finalBossRematchLockedMessage || `Complete ${saga?.name || "this saga"} first`
    };
  }

  function getActiveMythosStage(areaId = getSaved()?.currentArea) {
    const stage = getStage(areaId);
    const area = getAreas()?.[areaId];
    if (!stage || !area || area.type !== SAGA_TYPE || !isSagaView(area.mythosSaga)) return undefined;
    return stage;
  }

  function getActiveStageCombatRules(areaId = getSaved()?.currentArea) {
    const stage = getActiveMythosStage(areaId);
    return stage ? getStageCombatRules(stage) : {};
  }

  function ensureProgress(api = runtime.api) {
    const save = api?.saved || getSaved();
    if (!save) return {};
    if (!save.mythos || typeof save.mythos !== "object") save.mythos = {};
    getArcIds().forEach(arcId => {
      if (!save.mythos[arcId] || typeof save.mythos[arcId] !== "object") {
        save.mythos[arcId] = {};
      }
      const arcProgress = save.mythos[arcId];
      getSagasForArc(arcId).forEach(sagaId => {
        if (!arcProgress[sagaId] || typeof arcProgress[sagaId] !== "object") {
          arcProgress[sagaId] = { completed: {}, highest: 0 };
        }
        if (!arcProgress[sagaId].completed || typeof arcProgress[sagaId].completed !== "object") {
          arcProgress[sagaId].completed = {};
        }
        arcProgress[sagaId].highest = Number(arcProgress[sagaId].highest || 0);
      });
      if (!arcProgress.pendingChoices || typeof arcProgress.pendingChoices !== "object") {
        arcProgress.pendingChoices = {};
      }
    });
    return save.mythos;
  }

  function getArcProgress(arcId, api = runtime.api) {
    const mythosProgress = ensureProgress(api);
    return mythosProgress?.[arcId];
  }

  function getSagaProgress(sagaId, api = runtime.api) {
    const saga = getSagaConfig(sagaId);
    const arcProgress = saga ? getArcProgress(saga.arcId, api) : undefined;
    return arcProgress?.[sagaId] || { completed: {}, highest: 0 };
  }

  function defineSagaAreas(api = runtime.api) {
    const areaMap = api?.areas || getAreas();
    const pokemonMap = api?.pkmn || getPokemon();
    if (!areaMap || !pokemonMap) return;

    for (const stage of STAGES) {
      const saga = getSagaConfig(stage.sagaId);
      const progress = getSagaProgress(stage.sagaId, api);
      const existing = areaMap[stage.areaId] || {};
      const completed = existing.defeated === true || progress.completed[stage.areaId] === true;
      const fieldEffects = Array.isArray(existing.fieldEffect) ? [...existing.fieldEffect] : [];
      const battleRules = getStageCombatRules(stage);
      const fieldEffectId = battleRules.weather?.fieldKey ? getFields()?.[battleRules.weather.fieldKey]?.id : undefined;
      if (fieldEffectId && !fieldEffects.includes(fieldEffectId)) {
        fieldEffects.push(fieldEffectId);
      }

      areaMap[stage.areaId] = {
        ...existing,
        id: stage.areaId,
        name: stage.floorIndex ? `Floor ${stage.floorIndex}: ${stage.title}` : stage.finalBattle ? saga.bossName : stage.trainerName,
        background: stage.finalBattle ? (saga.finalBattleBackground || saga.battleBackground) : saga.battleBackground,
        icon: pokemonMap[stage.icon] || pokemonMap[saga.iconFallback],
        trainer: true,
        type: SAGA_TYPE,
        mythosArc: saga.arcId,
        mythosSaga: stage.sagaId,
        mythosEnemyIvs: ENEMY_IV_VALUE,
        difficulty: stage.finalBattle ? getTier2Difficulty() : 9,
        level: stage.battleLevel,
        tier: stage.finalBattle ? 2 : undefined,
        encounter: stage.finalBattle === true ? true : undefined,
        fieldEffect: fieldEffects.length ? fieldEffects : undefined,
        team: buildTeam(stage, pokemonMap, api?.move || getMoves()),
        reward: buildReward(stage, pokemonMap, completed),
        itemReward: buildItemReward(stage, api?.item || getItems(), completed),
        defeated: completed,
        unlockRequirement: () => isStageUnlocked(stage.areaId),
        unlockDescription: getUnlockDescription(stage),
        encounterEffect: () => markStageCompleted(stage.areaId)
      };
    }
  }

  function buildTeam(stage, pokemonMap, moveMap) {
    const result = {};
    const saga = getSagaConfig(stage.sagaId);
    stage.team.forEach((entry, index) => {
      const slot = index + 1;
      result[`slot${slot}`] =
        pokemonMap[entry.pkmn] ||
        pokemonMap[stage.rewardPokemon] ||
        pokemonMap[saga?.iconFallback] ||
        pokemonMap.groudon;
      result[`slot${slot}Moves`] = resolveMoves(entry.moves, moveMap);
    });
    return result;
  }

  function resolveMoves(ids, moveMap) {
    const fallback = moveMap?.tackle?.id || "tackle";
    const resolved = (ids || []).map(id => moveMap?.[id]?.id).filter(Boolean);
    while (resolved.length < 1) resolved.push(fallback);
    return resolved.slice(0, 4);
  }

  function buildReward(stage, pokemonMap, completed) {
    if (!stage.rewardPokemon) return undefined;
    const repeatPokemonReward = stage.repeatRewardPokemon === true || stage.finalBattle === true;
    if (completed && !repeatPokemonReward) return undefined;
    const reward = pokemonMap[stage.rewardPokemon];
    return reward ? [reward] : undefined;
  }

  function buildItemReward(stage, itemMap, completed) {
    if (completed || !Array.isArray(stage.rewardItems)) return undefined;
    const rewards = {};
    stage.rewardItems.forEach((entry, index) => {
      if (!itemMap?.[entry.id]) return;
      rewards[index + 1] = { item: entry.id, amount: entry.amount || 1 };
    });
    return Object.keys(rewards).length > 0 ? rewards : undefined;
  }

  function getTier3Difficulty() {
    try {
      return typeof tier3difficulty === "undefined" ? 200 : tier3difficulty;
    } catch (error) {
      return 200;
    }
  }

  function getTier2Difficulty() {
    try {
      return typeof tier2difficulty === "undefined" ? 70 : tier2difficulty;
    } catch (error) {
      return 70;
    }
  }

  function getUnlockDescription(stage) {
    const saga = getSagaConfig(stage.sagaId);
    const arc = getArcForSaga(stage.sagaId);
    if (arc && !isArcUnlocked(arc.id)) return getArcUnlockDescription(arc.id);
    if (!isSagaRequirementUnlocked(stage.sagaId)) return getSagaRequirementDescription(stage.sagaId);
    const sagaStages = getStagesForSaga(stage.sagaId);
    const index = sagaStages.findIndex(item => item.areaId === stage.areaId);
    if (index <= 0) return "Saga unlocked";
    return `Defeat ${sagaStages[index - 1].title} first`;
  }

  function allVsTrainersDefeated() {
    const areaMap = getAreas();
    if (!areaMap) return false;

    let total = 0;
    for (const id in areaMap) {
      const area = areaMap[id];
      if (!area || area.type !== "vs" || area.trainer !== true) continue;
      total++;
      if (area.defeated !== true) return false;
    }
    return total > 0;
  }

  function isStageUnlocked(areaId) {
    const stage = getStage(areaId);
    if (!stage) return false;
    const saga = getSagaConfig(stage.sagaId);
    const arc = saga ? getArcConfig(saga.arcId) : undefined;
    if (arc && !isArcUnlocked(arc.id)) return false;
    if (!isSagaRequirementUnlocked(stage.sagaId)) return false;
    const sagaStages = getStagesForSaga(stage.sagaId);
    const index = sagaStages.findIndex(item => item.areaId === areaId);
    if (index < 0) return false;
    if (index === 0) return true;
    return isStageCompleted(sagaStages[index - 1].areaId);
  }

  function isStageCompleted(areaId) {
    const stage = getStage(areaId);
    if (!stage) return false;
    const progress = getSagaProgress(stage.sagaId);
    const area = getAreas()?.[areaId];
    return progress.completed[areaId] === true || area?.defeated === true;
  }

  function isSagaCompleted(sagaId) {
    const stages = getStagesForSaga(sagaId);
    return stages.length > 0 && stages.every(stage => isStageCompleted(stage.areaId));
  }

  function arePrimordialRematchesUnlocked() {
    return isSagaCompleted(RAYQUAZA_SAGA_ID);
  }

  function canRematchStage(stage) {
    if (!stage || !isStageCompleted(stage.areaId)) return false;
    if (!stage.finalBattle) return true;
    const saga = getSagaConfig(stage.sagaId);
    if (typeof saga?.finalBossRematchRequirement === "function") {
      return saga.finalBossRematchRequirement(stage) === true;
    }
    return true;
  }

  function syncProgressFromAreas(api = runtime.api) {
    const areaMap = api?.areas || getAreas();
    const arc = ensureProgress(api);
    if (!areaMap || !arc) return false;

    let changed = false;
    getSagaIds().forEach(sagaId => {
      const progress = getSagaProgress(sagaId, api);
      const stages = getStagesForSaga(sagaId);
      let highest = 0;

      stages.forEach((stage, index) => {
        if (areaMap[stage.areaId]?.defeated === true && progress.completed[stage.areaId] !== true) {
          progress.completed[stage.areaId] = true;
          changed = true;
        }
        if (progress.completed[stage.areaId] === true) highest = index + 1;
      });

      if (progress.highest !== highest) {
        progress.highest = highest;
        changed = true;
      }
    });

    if (changed) {
      defineSagaAreas(api);
      api?.save?.();
    }
    return changed;
  }

  function markStageCompleted(areaId, api = runtime.api) {
    const stage = getStage(areaId);
    if (!stage) return false;
    const progress = getSagaProgress(stage.sagaId, api);
    if (!progress || progress.completed[areaId] === true) return false;

    progress.completed[areaId] = true;
    const index = getStagesForSaga(stage.sagaId).findIndex(item => item.areaId === areaId);
    if (index >= 0) progress.highest = Math.max(Number(progress.highest || 0), index + 1);
    api?.save?.();
    return true;
  }

  function prepareSagaAreaReward(areaId) {
    const stage = getStage(areaId);
    if (!stage) return;
    defineSagaAreas(runtime.api);
  }

